import{_ as t,C as i,o as n,c as r,E as s,a2 as o}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"Guardrails Need a Persistence State Machine, Not a Later Save Call","description":"","frontmatter":{"title":"Guardrails Need a Persistence State Machine, Not a Later Save Call","date":"2026-08-05","column":"open-source-engineering","category":"daily","summary":"Deferring final-message persistence until guardrails complete is necessary, but accepted output, retained tool evidence and replayable failure material still need different durable states.","item_id":"Q-20260805-14","source_research_object":"research/analysis/Q-20260805-14-guardrail-session-ordering.md","source_reading_result":"research/reading/Q-20260805-14-guardrail-session-ordering.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-05-guardrail-persistence-state-machine-cover-v2.jpg"},"headers":[],"relativePath":"en/engineering/2026-08-05-guardrail-persistence-state-machine.md","filePath":"en/engineering/2026-08-05-guardrail-persistence-state-machine.md","lastUpdated":1787407830000}'),l={name:"en/engineering/2026-08-05-guardrail-persistence-state-machine.md"};function c(d,e,u,p,h,m){const a=i("ArticleCover");return n(),r("div",null,[s(a,{image:"/assets/covers/daily-2026-08-05-guardrail-persistence-state-machine-cover-v2.jpg",kicker:"Open-source Engineering · Daily Research",title:"Guardrails Need a Persistence State Machine, Not a Later Save Call",summary:"Deferring final-message persistence until guardrails complete is necessary, but accepted output, retained tool evidence and replayable failure material still need different durable states.",version:"Q-20260805-14",status:"Daily Runtime V5 · 2026-08-05",languageHref:"/zh/engineering/2026-08-05-guardrail-persistence-state-machine",languageLabel:"中文"}),e[0]||(e[0]=o('<h1 id="guardrails-need-a-persistence-state-machine-not-a-later-save-call" tabindex="-1">Guardrails Need a Persistence State Machine, Not a Later Save Call <a class="header-anchor" href="#guardrails-need-a-persistence-state-machine-not-a-later-save-call" aria-label="Permalink to &quot;Guardrails Need a Persistence State Machine, Not a Later Save Call&quot;">​</a></h1><p>Deferring final-message persistence until guardrails complete is necessary, but accepted output, retained tool evidence and replayable failure material still need different durable states.</p><h2 id="core-judgment" tabindex="-1">Core judgment <a class="header-anchor" href="#core-judgment" aria-label="Permalink to &quot;Core judgment&quot;">​</a></h2><p>Finalization is a typed state machine, not one save operation.</p><h2 id="why-this-is-not-a-point-feature" tabindex="-1">Why this is not a point feature <a class="header-anchor" href="#why-this-is-not-a-point-feature" aria-label="Permalink to &quot;Why this is not a point feature&quot;">​</a></h2><p>A blocked assistant message does not imply a rolled-back turn: tool calls, tool outputs and external effects may already exist. Error and cancellation paths may intentionally retain otherwise undelivered output for replayability. One undifferentiated conversation log cannot safely represent accepted truth and forensic evidence at the same time.</p><h2 id="minimum-deployable-architecture" tabindex="-1">Minimum deployable architecture <a class="header-anchor" href="#minimum-deployable-architecture" aria-label="Permalink to &quot;Minimum deployable architecture&quot;">​</a></h2><p>Model Provisional, GuardrailEvaluated, Accepted, BlockedWithRetainedEvidence, QuarantinedError, CancelledReplayable and Persisted states. Store accepted output separately from retained execution evidence. Give every consequential external effect an idempotency key and effect receipt independent of message persistence.</p><h2 id="boundaries-and-counter-evidence" tabindex="-1">Boundaries and counter-evidence <a class="header-anchor" href="#boundaries-and-counter-evidence" aria-label="Permalink to &quot;Boundaries and counter-evidence&quot;">​</a></h2><p>The demonstrated tests use fake models and a simple list session. They do not prove atomic storage, rollback, exactly-once effects, concurrent-writer safety or correctness across distributed resume.</p><h2 id="engineering-conclusion" tabindex="-1">Engineering conclusion <a class="header-anchor" href="#engineering-conclusion" aria-label="Permalink to &quot;Engineering conclusion&quot;">​</a></h2><p>Introduce an explicit FinalizationDecision before accepted-output projection, quarantine replay evidence, and test crash boundaries against the real persistence adapter and effect system.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The diagram represents control boundaries and state relationships. It does not present experimental results or invent quantitative comparisons absent from the Research Object.</p><h2 id="evidence-and-citations" tabindex="-1">Evidence and citations <a class="header-anchor" href="#evidence-and-citations" aria-label="Permalink to &quot;Evidence and citations&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260805-14-guardrail-session-ordering.md" target="_blank" rel="noreferrer">Research Object</a>: the sole analytical input, including judgments, uncertainty, counter-evidence and engineering implications.</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260805-14-guardrail-session-ordering.md" target="_blank" rel="noreferrer">Reading Result</a>: the evidence boundary and source-trace record behind the Research Object.</li></ol>',16))])}const b=t(l,[["render",c]]);export{f as __pageData,b as default};
